		"ask": "Write `pub fn abbreviate(phrase: &str) -> String`. Convert a phrase to its acronym. Techies love their TLA (Three Letter Acronyms)! Help generate some jargon by writing a program that converts a long name like Portable Network Graphics to its acronym (PNG). Punctuation is handled as follows: hyphens are word separators (like whitespace); all other punctuation can be removed from the input. For example: | Input | Output | | ------------------------- | ------ | | As Soon As Possible | ASAP | | Liquid-crystal display | LCD | | Thank George It's Friday! | TGIF |",
		"code": "pub fn abbreviate(phrase: &str) -> String {\n    phrase\n        .split(|c: char| c.is_whitespace() || (c != '\\'' && !c.is_alphanumeric()))\n        .flat_map(split_camel)\n        .filter_map(|word| word.chars().next())\n        .collect::<String>()\n        .to_uppercase()\n}\n\nfn split_camel(phrase: &str) -> Vec<String> {\n    let chars: Vec<char> = phrase.chars().collect();\n    let mut words: Vec<String> = Vec::new();\n    let mut word_start: usize = 0;\n    for (i, c) in chars.iter().enumerate() {\n        if i == chars.len() - 1 || c.is_lowercase() && chars[i + 1].is_uppercase() {\n            words.push(chars[word_start..=i].iter().cloned().collect());\n            word_start = i + 1;\n        }\n    }\n    words\n}\n",
		"testsModule": "#[cfg(test)]\nmod hidden_tests {\n    use super::*;\n\n    #[test]\n    fn basic() {\n        let input = \"Portable Network Graphics\";\n        let output = abbreviate(input);\n        let expected = \"PNG\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn lowercase_words() {\n        let input = \"Ruby on Rails\";\n        let output = abbreviate(input);\n        let expected = \"ROR\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn punctuation() {\n        let input = \"First In, First Out\";\n        let output = abbreviate(input);\n        let expected = \"FIFO\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn all_caps_word() {\n        let input = \"GNU Image Manipulation Program\";\n        let output = abbreviate(input);\n        let expected = \"GIMP\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn punctuation_without_whitespace() {\n        let input = \"Complementary metal-oxide semiconductor\";\n        let output = abbreviate(input);\n        let expected = \"CMOS\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn very_long_abbreviation() {\n        let input = \"Rolling On The Floor Laughing So Hard That My Dogs Came Over And Licked Me\";\n        let output = abbreviate(input);\n        let expected = \"ROTFLSHTMDCOALM\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn consecutive_delimiters() {\n        let input = \"Something - I made up from thin air\";\n        let output = abbreviate(input);\n        let expected = \"SIMUFTA\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn apostrophes() {\n        let input = \"Halley's Comet\";\n        let output = abbreviate(input);\n        let expected = \"HC\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn underscore_emphasis() {\n        let input = \"The Road _Not_ Taken\";\n        let output = abbreviate(input);\n        let expected = \"TRNT\";\n        assert_eq!(output, expected);\n    }\n\n    #[test]\n    fn camelcase() {\n        let input = \"HyperText Markup Language\";\n        let output = abbreviate(input);\n        let expected = \"HTML\";\n        assert_eq!(output, expected);\n    }\n}\n",
