		"id": "ex_grains",
		"kind": "fn",
		"ask": "Write `pub fn square(s: u32) -> u64`, `pub fn total() -> u64`. Calculate the number of grains of wheat on a chessboard. A chessboard has 64 squares. Square 1 has one grain, square 2 has two grains, square 3 has four grains, and so on, doubling each time. Write code that calculates: - the number of grains on a given square - the total number of grains on the chessboard",
		"code": "pub fn square(s: u32) -> u64 {\n    if s == 0 || s > 64 {\n        panic!(\"Square must be between 1 and 64\");\n    }\n\n    2u64.pow(s - 1)\n}\n\npub fn total() -> u64 {\n    (1..65).fold(0, |acc, s| acc + square(s))\n}\n",
		"testsModule": "#[cfg(test)]\nmod hidden_tests {\n    use super::*;\n\n    #[test]\n    fn grains_on_square_1() {\n        assert_eq!(square(1), 1);\n    }\n\n    #[test]\n    fn grains_on_square_2() {\n        assert_eq!(square(2), 2);\n    }\n\n    #[test]\n    fn grains_on_square_3() {\n        assert_eq!(square(3), 4);\n    }\n\n    #[test]\n    fn grains_on_square_4() {\n        assert_eq!(square(4), 8);\n    }\n\n    #[test]\n    fn grains_on_square_16() {\n        assert_eq!(square(16), 32_768);\n    }\n\n    #[test]\n    fn grains_on_square_32() {\n        assert_eq!(square(32), 2_147_483_648);\n    }\n\n    #[test]\n    fn grains_on_square_64() {\n        assert_eq!(square(64), 9_223_372_036_854_775_808);\n    }\n\n    #[test]\n    #[should_panic]\n    fn square_0_is_invalid() {\n        square(0);\n    }\n\n    #[test]\n    #[should_panic]\n    fn square_greater_than_64_is_invalid() {\n        square(65);\n    }\n    #[test]\n    fn returns_the_total_number_of_grains_on_the_board() {\n        assert_eq!(total(), 18_446_744_073_709_551_615);\n    }\n}\n",
