		"id": "al_n_bits_gray_code",
		"kind": "fn",
		"ask": "Write `#[derive(Debug, PartialEq)] pub enum GrayCodeError { ZeroBitCount, }`, `pub fn generate_gray_code(n: usize) -> Result<Vec<String>, GrayCodeError>` (bit manipulation: n bits gray code). Custom error type for Gray code generation.",
		"code": "#[derive(Debug, PartialEq)]\npub enum GrayCodeError {\n    ZeroBitCount,\n}\n\npub fn generate_gray_code(n: usize) -> Result<Vec<String>, GrayCodeError> {\n    if n == 0 {\n        return Err(GrayCodeError::ZeroBitCount);\n    }\n\n    let num_codes = 1 << n;\n    let mut result = Vec::with_capacity(num_codes);\n\n    for i in 0..num_codes {\n        let gray = i ^ (i >> 1);\n        let gray_code = (0..n)\n            .rev()\n            .map(|bit| if gray & (1 << bit) != 0 { '1' } else { '0' })\n            .collect::<String>();\n        result.push(gray_code);\n    }\n\n    Ok(result)\n}\n",
		"testsModule": "#[cfg(test)]\nmod tests {\n    use super::*;\n\n    macro_rules! gray_code_tests {\n        ($($name:ident: $test_case:expr,)*) => {\n            $(\n                #[test]\n                fn $name() {\n                    let (input, expected) = $test_case;\n                    assert_eq!(generate_gray_code(input), expected);\n                }\n            )*\n        };\n    }\n\n    gray_code_tests! {\n        zero_bit_count: (0, Err(GrayCodeError::ZeroBitCount)),\n        gray_code_1_bit: (1, Ok(vec![\n            \"0\".to_string(),\n            \"1\".to_string(),\n        ])),\n        gray_code_2_bit: (2, Ok(vec![\n            \"00\".to_string(),\n            \"01\".to_string(),\n            \"11\".to_string(),\n            \"10\".to_string(),\n        ])),\n        gray_code_3_bit: (3, Ok(vec![\n            \"000\".to_string(),\n            \"001\".to_string(),\n            \"011\".to_string(),\n            \"010\".to_string(),\n            \"110\".to_string(),\n            \"111\".to_string(),\n            \"101\".to_string(),\n            \"100\".to_string(),\n        ])),\n    }\n}\n",
