		"id": "al_vigenere",
		"kind": "fn",
		"ask": "Write `pub fn vigenere(plain_text: &str, key: &str) -> String` (ciphers: vigenere). Vigenère Cipher # Algorithm Rotate each ascii character by the offset of the corresponding key character. When we reach the last key character, we start over from the first one. This implementation does not rotate unicode characters.",
		"code": "pub fn vigenere(plain_text: &str, key: &str) -> String {\n    let key: String = key.chars().filter(|&c| c.is_ascii_alphabetic()).collect();\n    let key = key.to_ascii_lowercase();\n\n    let key_len = key.len();\n    if key_len == 0 {\n        return String::from(plain_text);\n    }\n\n    let mut index = 0;\n\n    plain_text\n        .chars()\n        .map(|c| {\n            if c.is_ascii_alphabetic() {\n                let first = if c.is_ascii_lowercase() { b'a' } else { b'A' };\n                let shift = key.as_bytes()[index % key_len] - b'a';\n                index += 1;\n                (first + (c as u8 + shift - first) % 26) as char\n            } else {\n                c\n            }\n        })\n        .collect()\n}\n",
		"testsModule": "#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn empty() {\n        assert_eq!(vigenere(\"\", \"test\"), \"\");\n    }\n\n    #[test]\n    fn vigenere_base() {\n        assert_eq!(\n            vigenere(\"LoremIpsumDolorSitAmet\", \"base\"),\n            \"MojinIhwvmVsmojWjtSqft\"\n        );\n    }\n\n    #[test]\n    fn vigenere_with_spaces() {\n        assert_eq!(\n            vigenere(\n                \"Lorem ipsum dolor sit amet, consectetur adipiscing elit.\",\n                \"spaces\"\n            ),\n            \"Ddrgq ahhuo hgddr uml sbev, ggfheexwljr chahxsemfy tlkx.\"\n        );\n    }\n\n    #[test]\n    fn vigenere_unicode_and_numbers() {\n        assert_eq!(\n            vigenere(\"1 Lorem ⏳ ipsum dolor sit amet Ѡ\", \"unicode\"),\n            \"1 Fbzga ⏳ ltmhu fcosl fqv opin Ѡ\"\n        );\n    }\n\n    #[test]\n    fn vigenere_unicode_key() {\n        assert_eq!(\n            vigenere(\"Lorem ipsum dolor sit amet\", \"😉 key!\"),\n            \"Vspoq gzwsw hmvsp cmr kqcd\"\n        );\n    }\n\n    #[test]\n    fn vigenere_empty_key() {\n        assert_eq!(vigenere(\"Lorem ipsum\", \"\"), \"Lorem ipsum\");\n    }\n}\n",
