		"id": "al_rgb_cmyk_conversion",
		"kind": "fn",
		"ask": "Write `pub fn rgb_to_cmyk(rgb: (u8, u8, u8)) -> (u8, u8, u8, u8)` (conversions: rgb cmyk conversion). Author : https://github.com/ali77gh\\ References:\\ RGB: https://en.wikipedia.org/wiki/RGB_color_model\\ CMYK: https://en.wikipedia.org/wiki/CMYK_color_model\\",
		"code": "pub fn rgb_to_cmyk(rgb: (u8, u8, u8)) -> (u8, u8, u8, u8) {\n\n    let (r, g, b) = (\n        rgb.0 as f64 / 255f64,\n        rgb.1 as f64 / 255f64,\n        rgb.2 as f64 / 255f64,\n    );\n\n    match 1f64 - r.max(g).max(b) {\n        1f64 => (0, 0, 0, 100), // pure black\n        k => (\n            (100f64 * (1f64 - r - k) / (1f64 - k)) as u8, // c\n            (100f64 * (1f64 - g - k) / (1f64 - k)) as u8, // m\n            (100f64 * (1f64 - b - k) / (1f64 - k)) as u8, // y\n            (100f64 * k) as u8,                           // k\n        ),\n    }\n}\n",
		"testsModule": "#[cfg(test)]\nmod tests {\n    use super::*;\n\n    macro_rules! test_rgb_to_cmyk {\n        ($($name:ident: $tc:expr,)*) => {\n            $(\n                #[test]\n                fn $name() {\n                    let (rgb, cmyk) = $tc;\n                    assert_eq!(rgb_to_cmyk(rgb), cmyk);\n                }\n            )*\n        }\n    }\n\n    test_rgb_to_cmyk! {\n        white: ((255, 255, 255), (0, 0, 0, 0)),\n        gray: ((128, 128, 128), (0, 0, 0, 49)),\n        black: ((0, 0, 0), (0, 0, 0, 100)),\n        red: ((255, 0, 0), (0, 100, 100, 0)),\n        green: ((0, 255, 0), (100, 0, 100, 0)),\n        blue: ((0, 0, 255), (100, 100, 0, 0)),\n    }\n}\n",
