		"code": "pub fn npv_sensitivity(cash_flows: &[f64], discount_rates: &[f64]) -> Vec<f64> {\n    discount_rates\n        .iter()\n        .cloned()\n        .map(|rate| {\n            cash_flows\n                .iter()\n                .enumerate()\n                .map(|(t, &cf)| cf / (1.0 + rate).powi(t as i32))\n                .sum()\n        })\n        .collect()\n}\n",
