		"kind": "fn",
		"ask": "Write `pub fn mex_using_set(arr: &[i64]) -> i64`, `pub fn mex_using_sort(arr: &[i64]) -> i64` (general: mex). Finds the MEX of the values provided in `arr` Uses [`BTreeSet`](std::collections::BTreeSet) O(nlog(n)) implementation",
		"code": "use std::collections::BTreeSet;\n\npub fn mex_using_set(arr: &[i64]) -> i64 {\n    let mut s: BTreeSet<i64> = BTreeSet::new();\n    for i in 0..=arr.len() {\n        s.insert(i as i64);\n    }\n    for x in arr {\n        s.remove(x);\n    }\n    if let Some(x) = s.into_iter().next() {\n        x\n    } else {\n        panic!(\"Some unknown error in mex_using_set\")\n    }\n}\npub fn mex_using_sort(arr: &[i64]) -> i64 {\n    let mut arr = arr.to_vec();\n    arr.sort();\n    let mut mex = 0;\n    for x in arr {\n        if x == mex {\n            mex += 1;\n        }\n    }\n    mex\n}\n",
		"testsModule": "#[cfg(test)]\nmod tests {\n    use super::*;\n    struct MexTests {\n        test_arrays: Vec<Vec<i64>>,\n        outputs: Vec<i64>,\n    }\n    impl MexTests {\n        fn new() -> Self {\n            Self {\n                test_arrays: vec![\n                    vec![-1, 0, 1, 2, 3],\n                    vec![-100, 0, 1, 2, 3, 5],\n                    vec![-1000000, 0, 1, 2, 5],\n                    vec![2, 0, 1, 2, 4],\n                    vec![1, 2, 3, 0, 4],\n                    vec![0, 1, 5, 2, 4, 3],\n                    vec![0, 1, 2, 3, 4, 5, 6],\n                    vec![0, 1, 2, 3, 4, 5, 6, 7],\n                    vec![0, 1, 2, 3, 4, 5, 6, 7, 8],\n                ],\n                outputs: vec![4, 4, 3, 3, 5, 6, 7, 8, 9],\n            }\n        }\n        fn test_function(&self, f: fn(&[i64]) -> i64) {\n            for (nums, output) in self.test_arrays.iter().zip(self.outputs.iter()) {\n                assert_eq!(f(nums), *output);\n            }\n        }\n    }\n    #[test]\n    fn test_mex_using_set() {\n        let tests = MexTests::new();\n        mex_using_set(&[1, 23, 3]);\n        tests.test_function(mex_using_set);\n    }\n    #[test]\n    fn test_mex_using_sort() {\n        let tests = MexTests::new();\n        tests.test_function(mex_using_sort);\n    }\n}\n",
