		"code": "pub fn cross_entropy_loss(actual: &[f64], predicted: &[f64]) -> f64 {\n    let mut loss: Vec<f64> = Vec::new();\n    for (a, p) in actual.iter().zip(predicted.iter()) {\n        loss.push(-a * p.ln());\n    }\n    loss.iter().sum()\n}\n",
