		"code": "pub fn factors(number: u64) -> Vec<u64> {\n    let mut factors: Vec<u64> = Vec::new();\n\n    for i in 1..=((number as f64).sqrt() as u64) {\n        if number.is_multiple_of(i) {\n            factors.push(i);\n            if i != number / i {\n                factors.push(number / i);\n            }\n        }\n    }\n\n    factors.sort();\n    factors\n}\n",
