		"code": "pub fn fast_power(mut base: usize, mut power: usize, modulus: usize) -> usize {\n    assert!(base >= 1);\n\n    let mut res = 1;\n    while power > 0 {\n        if power & 1 == 1 {\n            res = (res * base) % modulus;\n        }\n        base = (base * base) % modulus;\n        power >>= 1;\n    }\n    res\n}\n",
