		"code": "pub fn linear_search<T: Ord>(item: &T, arr: &[T]) -> Option<usize> {\n    for (i, data) in arr.iter().enumerate() {\n        if item == data {\n            return Some(i);\n        }\n    }\n\n    None\n}\n",
