		"id": "al_ternary_search_min_max",
		"kind": "fn",
		"ask": "Write `pub fn ternary_search_max( f: fn(f32) -> f32, mut start: f32, mut end: f32, absolute_precision: f32, ) -> f32`, `pub fn ternary_search_min( f: fn(f32) -> f32, mut start: f32, mut end: f32, absolute_precision: f32, ) -> f32` (searching: ternary search min max). Ternary search algorithm for finding maximum of unimodal function",
		"code": "pub fn ternary_search_max(\n    f: fn(f32) -> f32,\n    mut start: f32,\n    mut end: f32,\n    absolute_precision: f32,\n) -> f32 {\n    while (start - end).abs() >= absolute_precision {\n        let mid1 = start + (end - start) / 3.0;\n        let mid2 = end - (end - start) / 3.0;\n\n        let r1 = f(mid1);\n        let r2 = f(mid2);\n\n        if r1 < r2 {\n            start = mid1;\n        } else if r1 > r2 {\n            end = mid2;\n        } else {\n            start = mid1;\n            end = mid2;\n        }\n    }\n    f(start)\n}\n\npub fn ternary_search_min(\n    f: fn(f32) -> f32,\n    mut start: f32,\n    mut end: f32,\n    absolute_precision: f32,\n) -> f32 {\n    while (start - end).abs() >= absolute_precision {\n        let mid1 = start + (end - start) / 3.0;\n        let mid2 = end - (end - start) / 3.0;\n\n        let r1 = f(mid1);\n        let r2 = f(mid2);\n\n        if r1 < r2 {\n            end = mid2;\n        } else if r1 > r2 {\n            start = mid1;\n        } else {\n            start = mid1;\n            end = mid2;\n        }\n    }\n    f(start)\n}\n",
		"testsModule": "#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn finds_max_value() {\n        let expected = 4.0;\n        let f = |x: f32| -x * x - 2.0 * x + 3.0;\n\n        let start: f32 = -10000000000.0;\n        let end: f32 = 10000000000.0;\n        let absolute_precision = 0.0000001;\n\n        let result = ternary_search_max(f, start, end, absolute_precision);\n\n        assert_eq!(result, expected);\n    }\n\n    #[test]\n    fn finds_min_value() {\n        let expected = 2.0;\n        let f = |x: f32| x * x - 2.0 * x + 3.0;\n\n        let start: f32 = -10000000000.0;\n        let end: f32 = 10000000000.0;\n        let absolute_precision = 0.0000001;\n\n        let result = ternary_search_min(f, start, end, absolute_precision);\n\n        assert_eq!(result, expected);\n    }\n\n    #[test]\n    fn finds_max_value_2() {\n        let expected = 7.25;\n        let f = |x: f32| -x.powi(2) + 3.0 * x + 5.0;\n\n        let start: f32 = -10000000000.0;\n        let end: f32 = 10000000000.0;\n        let absolute_precision = 0.000001;\n\n        let result = ternary_search_max(f, start, end, absolute_precision);\n\n        assert_eq!(result, expected);\n    }\n\n    #[test]\n    fn finds_min_value_2() {\n        let expected = 2.75;\n        let f = |x: f32| x.powi(2) + 3.0 * x + 5.0;\n\n        let start: f32 = -10000000000.0;\n        let end: f32 = 10000000000.0;\n        let absolute_precision = 0.000001;\n\n        let result = ternary_search_min(f, start, end, absolute_precision);\n\n        assert_eq!(result, expected);\n    }\n}\n",
